-- Carga do snapshot TSE de 12/08/2026 sobre a estrutura criada pela 20260813040000.
DO $$
DECLARE encontrados integer;
        coorte_presente integer;
        ledger_presente boolean;
BEGIN
  PERFORM set_config('pf.chapas_apply','false',true);
  SELECT count(*) INTO coorte_presente FROM public.candidatos WHERE slug IN ('eduardo-girao', 'luiz-carlos-teodoro', 'rafael-greca', 'francisco-dias', 'geraldo-alckmin', 'raquel-bricio', 'carlos-cley', 'ariel-capistrano', 'pedro-brito', 'reginaldo-lima', 'alexandre-salomao', 'samuel-de-mattos', 'arinalda-do-mlb', 'rodrigo-bolsonaro', 'farah-mesquita', 'policial-edjane', 'du-pereira', 'subtenente-luiz-carlos');
  IF coorte_presente = 0 THEN
    RAISE NOTICE 'banco vazio de replay; carga de chapas 2026 ignorada';
    RETURN;
  END IF;
  ledger_presente := false;
  IF to_regclass('supabase_migrations.schema_migrations') IS NOT NULL THEN
    EXECUTE 'SELECT EXISTS (SELECT 1 FROM supabase_migrations.schema_migrations WHERE version=''20260812130000'')' INTO ledger_presente;
  END IF;
  IF NOT ledger_presente THEN
    RAISE NOTICE 'replay linear sem ledger; carga de chapas 2026 ignorada com % dos 18 slugs sintéticos', coorte_presente;
    RETURN;
  END IF;
  PERFORM set_config('pf.chapas_apply','true',true);
  SELECT count(*) INTO encontrados
  FROM public.candidatos c
  JOIN (VALUES
    ('eduardo-girao', 'Governador', 'CE', 'Vice-Presidente', NULL),
    ('luiz-carlos-teodoro', 'Governador', 'RO', 'Vice-Governador', 'RO'),
    ('rafael-greca', 'Governador', 'PR', 'Vice-Governador', 'PR'),
    ('francisco-dias', 'Governador', 'RN', 'Vice-Governador', 'RN'),
    ('geraldo-alckmin', 'Governador', 'SP', 'Vice-Presidente', NULL),
    ('raquel-bricio', 'Governador', 'PA', 'Vice-Presidente', NULL)
  ) AS e(slug, cargo_antigo, uf_antiga, cargo_novo, uf_nova)
    ON e.slug = c.slug AND c.cargo_disputado = e.cargo_antigo
   AND c.estado IS NOT DISTINCT FROM e.uf_antiga;
  IF encontrados <> 6 THEN
    RAISE EXCEPTION 'pre-condição: esperava 6 papéis antigos exatos, encontrou %', encontrados;
  END IF;
  SELECT count(*) INTO encontrados FROM public.candidatos WHERE slug IN ('carlos-cley', 'ariel-capistrano', 'pedro-brito', 'reginaldo-lima', 'alexandre-salomao', 'samuel-de-mattos', 'arinalda-do-mlb', 'rodrigo-bolsonaro', 'farah-mesquita', 'policial-edjane', 'du-pereira', 'subtenente-luiz-carlos');
  IF encontrados <> 0 THEN
    RAISE EXCEPTION 'pre-condição: % dos 12 slugs oficiais novos já existem', encontrados;
  END IF;
END $$;

