-- @write tabela=candidatos slug=francisco-dias campos=cargo_disputado,estado,status,situacao_candidatura,publicavel,fonte_dados,ultima_atualizacao
-- @write tabela=candidatos slug=geraldo-alckmin campos=cargo_disputado,estado,status,situacao_candidatura,publicavel,fonte_dados,ultima_atualizacao
-- @write tabela=candidatos slug=raquel-bricio campos=cargo_disputado,estado,status,situacao_candidatura,publicavel,fonte_dados,ultima_atualizacao
UPDATE public.candidatos c
SET cargo_disputado = e.cargo_novo,
    estado = e.uf_nova,
    status = 'candidato',
    situacao_candidatura = 'pedido de registro no TSE; situação não informada no snapshot',
    publicavel = true,
    fonte_dados = CASE WHEN 'TSE consulta_cand 2026; snapshot 12/08/2026' = ANY(COALESCE(c.fonte_dados, ARRAY[]::text[]))
      THEN c.fonte_dados ELSE COALESCE(c.fonte_dados, ARRAY[]::text[]) || ARRAY['TSE consulta_cand 2026; snapshot 12/08/2026'] END,
    ultima_atualizacao = '2026-08-13T07:37:13Z'::timestamptz
FROM (VALUES
  ('eduardo-girao', 'Governador', 'CE', 'Vice-Presidente', NULL),
    ('luiz-carlos-teodoro', 'Governador', 'RO', 'Vice-Governador', 'RO'),
    ('rafael-greca', 'Governador', 'PR', 'Vice-Governador', 'PR'),
    ('francisco-dias', 'Governador', 'RN', 'Vice-Governador', 'RN'),
    ('geraldo-alckmin', 'Governador', 'SP', 'Vice-Presidente', NULL),
    ('raquel-bricio', 'Governador', 'PA', 'Vice-Presidente', NULL)
) AS e(slug, cargo_antigo, uf_antiga, cargo_novo, uf_nova)
WHERE c.slug = e.slug
  AND current_setting('pf.chapas_apply',true)='true';

