) AS v(chave,eleicao_codigo,eleicao_data,uf,cargo_titular,sq_coligacao,
       identidade_status,vinculo_titular_status,tse_situacao_codigo,
       tse_situacao_titular_codigo,tse_situacao_vice_codigo,tipo_agremiacao,composicao,
       titular_slug,vice_slug,titular_sq_candidato,vice_sq_candidato,
       titular_nome_completo,titular_nome_urna,titular_partido_sigla,
       vice_nome_completo,vice_nome_urna,vice_partido_sigla,alternativas_oficiais)
LEFT JOIN public.candidatos titular ON titular.slug = v.titular_slug
LEFT JOIN public.candidatos vice ON vice.slug = v.vice_slug
WHERE current_setting('pf.chapas_apply',true)='true';

DO $$
DECLARE total integer; confirmadas integer; duplicadas integer; vinculadas integer; revisoes integer;
BEGIN
  IF current_setting('pf.chapas_apply',true) IS DISTINCT FROM 'true' THEN RETURN; END IF;
  SELECT count(*), count(*) FILTER (WHERE identidade_status='confirmada'),
         count(*) FILTER (WHERE identidade_status='duplicidade_oficial'),
         count(*) FILTER (WHERE titular_candidato_id IS NOT NULL),
         count(*) FILTER (WHERE vinculo_titular_status='revisao_identidade')
    INTO total, confirmadas, duplicadas, vinculadas, revisoes FROM public.chapas_2026;
  IF total <> 134 THEN RAISE EXCEPTION 'esperava 134 chapas, encontrou %', total; END IF;
  IF confirmadas <> 133 THEN RAISE EXCEPTION 'esperava 133 identidades confirmadas, encontrou %', confirmadas; END IF;
  IF duplicadas <> 1 THEN RAISE EXCEPTION 'esperava 1 duplicidade oficial, encontrou %', duplicadas; END IF;
  IF vinculadas <> 113 THEN RAISE EXCEPTION 'esperava 113 vínculos seguros, encontrou %', vinculadas; END IF;
  IF revisoes <> 20 THEN RAISE EXCEPTION 'esperava 20 vínculos em revisão de identidade, encontrou %', revisoes; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.chapas_2026
    WHERE identidade_status='duplicidade_oficial' AND titular_nome_urna='ELIZEU AGUIAR'
      AND vinculo_titular_status = 'duplicidade_oficial'
      AND vice_nome_urna='ISMAR MARQUES' AND sq_coligacao IS NULL
      AND titular_sq_candidato IS NULL AND vice_sq_candidato IS NULL) THEN
    RAISE EXCEPTION 'duplicidade oficial Elizeu/Ismar não preservada em quarentena';
  END IF;
END $$;
